head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS90007.xml";
scwin.vMktactCd = "";
scwin.vBndApplId = "";
scwin.vPackApplId = '';
scwin.vBndListProcsTpCd = '3';
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_dtl_sync
 * 설명       : 그리드 선택 시 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var param = '';
    if (scwin.vBndListProcsTpCd == '3') {
        param += "&{P}V_BND_APPL_ID=" + scwin.vPackApplId; //채권신청ID		

    } else {
        param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID

    }
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    //종목정보
    var dsNm = 'BNS_ISU_INFO';
    var qryId = 'lds.stf.bnscommon.select.readIsuInfo';
    dts_IsuInfo.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);
    if (dts_IsuInfo.getTotalRow() > 0) {
        //한글금액표기
        $c.stf.setObjectValue(txb_AmtHan, $c.bns.fn_ChgAmtToHan(dts_IsuInfo.getCellData(1, 'LIST_AMT')));
        //금액여분적용
        scwin.fn_SetMargin();
    }

    //신용평가정보
    var dsNm = 'BNS_CREDIT_INFO';
    var qryId = 'lds.stf.bnscommon.select.listCredit';
    dts_Credit.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Credit, dsNm, qryId, param);
    if (dts_Credit.getTotalRow() > 0) {
        scwin.fn_SetCreditData();
    }

    //인수기관정보
    var dsNm = 'BNS_UDWRT_INST';
    var qryId = 'lds.stf.bnscommon.select.listUdwrtInst';
    dts_UdwrtInst.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_UdwrtInst, dsNm, qryId, param);
    if (dts_UdwrtInst.getTotalRow() > 0) {
        scwin.fn_SetUdwrtInstData();
    }

    //분할상환
    var dsNm = 'BNS_SPLIT_REDMPT';
    var qryId = 'lds.stf.bnscommon.select.listSplitRedmpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    //기관코드
    var dsNm = 'BNS_INST_INFO';
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, "&{P}V_INST_NM=");

    //공통콤보
    var arrCid = [];
    arrCid.push({
        cid: '02475',
        cnm: 'cmb_CurrTpCd'
    }); //발행통화				
    arrCid.push({
        cid: '01422',
        cnm: 'cmb_BndTpCd'
    }); //채권유형				
    arrCid.push({
        cid: '03076',
        cnm: 'cmb_MunibndTpCd'
    }); //지방채구분				
    arrCid.push({
        cid: '03221',
        cnm: 'cmb_NusualBndTpCd'
    }); //특이채권유형			
    arrCid.push({
        cid: '03055',
        cnm: 'cmb_BndGuarTpCd'
    }); //보증/담보				
    arrCid.push({
        cid: '00872',
        cnm: 'cmb_IntPayMethdCd'
    }); //이자지급방법			
    arrCid.push({
        cid: '03075',
        cnm: 'cmb_AsstSecutizTpCd'
    }); //유동화					
    arrCid.push({
        cid: '03054',
        cnm: 'cmb_ImbdoptCorpbndCd'
    }); //옵션					
    arrCid.push({
        cid: '03563',
        cnm: 'cmb_CondCapSecuTpCd'
    }); //조건부자본증권유형		
    arrCid.push({
        cid: '03053',
        cnm: 'cmb_DebtRepayRankTpCd'
    }); //선/후/중순위			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyPrincPayDdDecsnCd'
    }); //휴무관련(원금)			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyDdIntPayMethdCd'
    }); //휴무관련(이자)			
    arrCid.push({
        cid: '01513',
        cnm: 'cmb_CoupnPayMethdCd'
    }); //이자 선/후급			
    arrCid.push({
        cid: '03195',
        cnm: 'cmb_BndIntPayDdBasTpCd'
    }); //이자일지급구분			
    arrCid.push({
        cid: '03512',
        cnm: 'cmb_IntUdwonProcsCd'
    }); //이자원단위 미만처리		
    arrCid.push({
        cid: '03114',
        cnm: 'cmb_BndOddllotddIntBasTpCd'
    }); //단수일 이자기준			
    arrCid.push({
        cid: '01510',
        cnm: 'cmb_BndSaleTpCd'
    }); //매출형태				
    arrCid.push({
        cid: '02253',
        cnm: 'cmb_IntMmendTpCd'
    }); //이자월말구분			
    arrCid.push({
        cid: '01562',
        cnm: 'cmb_BndPreSaleIntPayMethdCd'
    }); //선매출시 이자지급방법	
    arrCid.push({
        cid: '03454',
        cnm: 'cmb_BndApctTpCd'
    }); //신청인구분				
    arrCid.push({
        cid: '03085',
        cnm: 'cmb_SplitRedmptTpCd'
    }); //분할상환구분	
    arrCid.push({
        cid: '03051',
        cnm: 'cmb_RedmptPdIntTpCd'
    }); //거치기간이자	
    arrCid.push({
        cid: '01430',
        cnm: 'cmb_BndStripTpCd'
    }); //스트립구분		
    $c.bns.fn_SetBnsComboToCode(scwin.vScrenID, dts_Temp, arrCid);
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISUR_NM: dts_IsuInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_IsuInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 반송 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetBndClss
 * 설명       : 채권분류 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetBndClss = function(arrPar) {
    arrPar[0] = {
        BND_CLSS_CD: "",
        BND_TP_NM: "",
        BND_TP_CD: $c.stf.getObjectValue(cmb_BndTpCd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetBndClss
 * 설명       : 채권분류 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetBndClss = function(arrPar) {
    $c.stf.setObjectValue(txb_BndTpNm, arrPar[0].BND_TP_NM1);
    dts_IsuInfo.setCellData(1, "BND_CLSS_CD", arrPar[0].BND_CLSS_CD);
};


/********************************************** 
 * 함수명   : fn_GetParInst
 * 설명       : 기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParInst = function(arrPar) {
    arrPar[0] = {
        INST_CD: $c.stf.getObjectValue(vSelObj),
        INST_NM: $c.stf.getObjectValue(vSelObj),
        LBL_NM: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParInst
 * 설명       : 기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParInst = function(arrPar) {
    $c.stf.setObjectValue(vSelObj, arrPar[0].INST_CD);
};


/********************************************** 
 * 함수명   : fn_ShowInst
 * 설명       : 기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowInst = function(selObj) {
    //if(vRowCount == 0) return;
    vSelObj = selObj;
    scwin.fn_GetPar = fn_GetParInst;
    scwin.fn_SetPar = fn_SetParInst;
    $c.bns.fn_PopInstSearch(selObj);
};


/********************************************** 
 * 함수명   : fn_SetCreditCombo
 * 설명       : 신용평가기관을 설정한다.
 ***********************************************/
scwin.fn_SetCreditCombo = function(obj, cd, val) {
    var cbdata = "^ ," + cd + "^" + val;
    obj.CBData = cbdata;
    $c.stf.setObjectValue(obj, cd);
};


/********************************************** 
 * 함수명   : fn_GetParBndBasNm
 * 설명       : 종목기준명 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParBndBasNm = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: dts_IsuInfo.getCellData(1, "ISUR_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParBndBasNm
 * 설명       : 종목기준명 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParBndBasNm = function(arrPar) {
    $c.stf.setObjectValue(txb_IsuNm, arrPar[0].BAS_ISU_NM);
    $c.stf.setObjectValue(txb_IsuAbbrv, arrPar[0].BAS_ISU_ABBRV);
    $c.stf.setObjectValue(txb_IsuEngNm, arrPar[0].BAS_ISU_ENG_NM);
    $c.stf.setObjectValue(txb_IsuEngAbbrv, arrPar[0].BAS_ISU_ENG_ABBRV);
};


/********************************************** 
 * 함수명   : fn_SetUdwrtInst
 * 설명       : 인수기관 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetUdwrtInst = function(rowIdx, cbObj, edtObj) {
    var UDWRT_INST_CD = dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_INST_CD');
    if (UDWRT_INST_CD == '9999') {
        $c.stf.setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_AMT'));
    } else {
        $c.stf.setObjectValue(cbObj, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_INST_CD'));
        $c.stf.setObjectValue(edtObj, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_AMT'));
    }
};



/********************************************** 
 * 함수명   : fn_SetDtlTab
 * 설명       : 상세탭을 설정한다.
 ***********************************************/
scwin.fn_SetDtlTab = function() {
    //기본
    var bsTab = '';
    bsTab += '<T>divid="pnl_IsurCond"	title="발행조건"</T>';
    bsTab += '<T>divid="pnl_RelInst"	title="관련기관"</T>';
    bsTab += '<T>divid="pnl_SplitRedmpt"	title="분할상환"</T>';
    //bsTab += '<T>divid="pnl_Strip"	title="스트립"</T>';

    //국채
    if (scwin.vMktactCd == '112') {
        if (scwin.vBndListProcsTpCd == '2') {
            bsTab += '<T>divid="pnl_Strip"	title="스트립"</T>';
        }
    }
    //지방채
    if (scwin.vMktactCd == "122") {
        //기본


        //특수채

    } else if (scwin.vMktactCd == "132") {
        //기본

    }
    tab_Detail.Format = bsTab;
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.vBndApplId = arrPar[0].BND_APPL_ID;
        scwin.vMktactCd = arrPar[0].BND_MKTACT_TP_CD;
        scwin.fn_SetPackApplId();
    }
};



/********************************************** 
 * 함수명   : fn_SetPackApplId
 * 설명       : 일괄상장번호를 설정한다.
 ***********************************************/
scwin.fn_SetPackApplId = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnscommon.select.readPackAapplId';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Temp, dsNm, qryId, param);
    scwin.vPackApplId = dts_Temp.getCellData(1, 'VALUE');
};


/********************************************** 
 * 함수명   : fn_SetMargin
 * 설명       : 금액, 비율에 마진을 적용한다.
 ***********************************************/
scwin.fn_SetMargin = function() {
    var margin = 5;
    edt_IsuAmt.RightMargin = margin;
    edt_ListAmt.RightMargin = margin;
    edt_GrtRt.RightMargin = margin;
    edt_CoupnRt.RightMargin = margin;
    edt_ScbdInt.RightMargin = margin;
    edt_BndIsuPrc.RightMargin = margin;
    edt_ExpRedmptRto.RightMargin = margin;
    edt_IsuDdRefIdx.RightMargin = margin;
    edt_BkHoldyDdPrincAcrintRt.RightMargin = margin;
    edt_BkHoldyDdIntCmpAcrintRt.RightMargin = margin;
    edt_IntPayUnitMms.RightMargin = margin;
    edt_IntPayCalcMms.RightMargin = margin;
    edt_GrtYd.RightMargin = margin;
    edt_AddYd.RightMargin = margin;
    edt_EqmtFnd.RightMargin = margin;
    edt_OperFnd.RightMargin = margin;
    edt_RefundFnd.RightMargin = margin;
    edt_MiscFnd.RightMargin = margin;
    edt_UdwrtAmt1.RightMargin = margin;
    edt_UdwrtAmt2.RightMargin = margin;
    edt_UdwrtAmt3.RightMargin = margin;
    edt_UdwrtAmt4.RightMargin = margin;
    edt_UdwrtAmt5.RightMargin = margin;
    edt_EquivRedmptVal.RightMargin = margin;
    edt_DefrMms.RightMargin = margin;
    edt_SplitRedmptCnt.RightMargin = margin;
    edt_StripNsprtBal.RightMargin = margin;
};


/********************************************** 
 * 함수명   : fn_SetCreditData
 * 설명       : 신용평가정보를 설정한다.
 ***********************************************/
scwin.fn_SetCreditData = function() {
    $c.stf.setObjectValue(cmb_CreditValuInstCd1, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd1, '0');
    $c.stf.setObjectValue(cmb_SfValuYn1, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd2, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd2, '0');
    $c.stf.setObjectValue(cmb_SfValuYn2, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd3, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd3, '0');
    $c.stf.setObjectValue(cmb_SfValuYn3, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd4, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd4, '0');
    $c.stf.setObjectValue(cmb_SfValuYn4, '');
    var rowcount = dts_Credit.getTotalRow();
    if (rowcount > 0) {
        for (var idx = 1; idx <= rowcount; idx++) {
            if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9201') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd1, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd1, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn1, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9202') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd2, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd2, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn2, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9203') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd3, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd3, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn3, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9204') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd4, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd4, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn4, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            }
        }
    }
};





/********************************************** 
 * 함수명   : fn_SetUdwrtInstData
 * 설명       : 인수기관정보를 설정한다.
 ***********************************************/
scwin.fn_SetUdwrtInstData = function() {
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd1, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt1, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd2, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt2, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd3, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt3, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd4, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt4, '');
    $c.stf.setObjectValue(edt_UdwrtAmt5, '');
    var rowcount = dts_UdwrtInst.getTotalRow();
    if (rowcount >= 1) {
        scwin.fn_SetUdwrtInst(1, cmb_BndUdwrtInstCd1, edt_UdwrtAmt1);
    }
    if (rowcount >= 2) {
        scwin.fn_SetUdwrtInst(2, cmb_BndUdwrtInstCd2, edt_UdwrtAmt2);
    }
    if (rowcount >= 3) {
        scwin.fn_SetUdwrtInst(3, cmb_BndUdwrtInstCd3, edt_UdwrtAmt3);
    }
    if (rowcount >= 4) {
        scwin.fn_SetUdwrtInst(4, cmb_BndUdwrtInstCd4, edt_UdwrtAmt4);
    }
    if (rowcount >= 5) {
        $c.stf.setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.getCellData(5, 'UDWRT_AMT'));
    }
};
scwin.gform_onload = function() {
    //탭지정
    tab_Detail.setSelectedTabIndex(1);

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
    $c.bns.BnsPanelToGroupBox(pnl_IsurCond);
    $c.bns.BnsPanelToGroupBox(pnl_RelInst);
    $c.bns.BnsPanelToGroupBox(pnl_SplitRedmpt);
    $c.bns.BnsPanelToGroupBox(pnl_Strip);

    //파라미터설정
    scwin.fn_SetParam();

    //탭설정
    scwin.fn_SetDtlTab();

    //콤보설정
    scwin.fn_SetComboCode();

    //종목조회
    scwin.fn_dtl_sync();
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.fn_SetDtlTab();
    scwin.vBndListProcsTpCd = nIndex;
    if (nIndex == 1) {
        scwin.vBndListProcsTpCd = '3';
    }
    scwin.fn_dtl_sync();
};
