scwin.btn_AttachDoc_onclick = function() {
    if (dts_IsuInfo.getTotalRow() == 0) return;
    if ("N" == dts_IsuInfo.getCellData(1, "HAS_ATTACH_DOC")) {
        $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
        return;
    }
    scwin.fn_GetPar = fn_GetCommonKey;
    $c.bns.fn_PopAttachDocSearch(img_BndTpNm);
};
